from jinja2 import Environment, pass_context, pass_eval_context, pass_environment
env = Environment()
@pass_context
def f1(ctx, v):
    return ctx['x'] + v
@pass_eval_context
def f2(ec, v):
    return str(ec.autoescape) + v
@pass_environment
def f3(e, v):
    return type(e).__name__ + v
env.filters.update(f1=f1, f2=f2, f3=f3)
assert env.from_string('{{ 1|f1 }}{{ "a"|f2 }}{{ "b"|f3 }}').render(x=2) == '3False' + 'a' + 'Environmentb'
